-- Card 4: p5-ets2023-test-3 (ETS 2023 Test 3 - Part 5)
INSERT INTO reading_exercise_cards (
    id, title, category, sub_category, subtitle, tag,
    total_questions, passage_text, passage_text_vi,
    passages, theory, sample_questions, order_index, created_at, updated_at
) VALUES (
    'p5-ets2023-test-3',
    'ETS 2023 Test 3 - Part 5',
    'part5',
    'levels',
    '30 câu hỏi ngữ pháp & từ vựng chuẩn đề ETS 2023 Test 3',
    'ETS 2023 · Test 3',
    30,
    NULL,
    NULL,
    '[]'::jsonb,
    '{"summary":"Toàn bộ 30 câu hỏi Part 5 chuẩn đề thi ETS 2023 Test 3, bao gồm kiểm tra từ loại, thì, liên từ và từ vựng ngữ cảnh.","rules":["Xác định từ loại và cấu trúc chỗ trống trước khi đọc cả câu.","Loại trừ các phương án sai thì, sai hòa hợp chủ vị hoặc sai giới từ đi kèm."],"example":"Video game designers need a broad ------- of computer programming."}'::jsonb,
    '[{"questionNum":"101","question":"Video game designers need a broad ------- of computer programming.","bilingual":"Các nhà thiết kế trò chơi điện tử cần có một tầm nhìn rộng -------của lập trình máy tính.","options":["knowledge","known","knowing","know"],"correctIndex":0,"explanation":"Chỗ trống cần điền một danh từ để tạo thành cụm danh từ làm tân ngữ trong câu, trongđó danh từ này được bổ nghĩa bởitính từ “broad” phía trước. - knowledge (N): kiến thức - known (V - PII): đuợc biết đến - knowing (V - ing): biết - know (V): biết *Cấu trúc:Need + to V: cần làm gìBroad (Adj): rộng lớn. Dịch: Những người thiết kếtrò chơi cần cóKI ẾN THỨC sâu rộng vềlập trình máy tính.","vocabList":[],"optionMeanings":["kiến ​​thức","đã biết","biết","biết"]},{"questionNum":"102","question":"Concerning the item that was lost in transit, we will take responsibility for- -------.","bilingual":"Về mặt hàng bị thất lạc trong quá trình vận chuyển, chúng tôi sẽ chịu trách nhiệm -------.","options":["it","its","its own","itself"],"correctIndex":0,"explanation":"Chỗ trống cần điền một đại từ làmtân ngữ đứng sau giới từ “for” thay thế cho dan h từ “item” phía trước. - it (đại từ làm tân ngữ) - its (tính từ sở hữu) - its own (nhấn mạnhđại từ phản thân) - itself (đại từ phản thân) *Cấu trúc: Transit (N): sự quá cảnhTake responsibility for: chịu trách nhiệm. Dịch: Đối với hàng hoá bị thất lạctrong lúcquá cảnh, chúng tôi sẽ chịu trách nhiệm đối với NÓ (hàng hoá đó).","vocabList":[{"word":"responsibility","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/rɪˌspɑːn.səˈbɪl.ə.t̬i/","meaning":"trách nhiệm; sự chịu trách nhiệm; bổn phận;"},{"word":"concern","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/kənˈsɝːn/","meaning":"mối bận tâm, chuyện đáng lo; liên quan, dính líu"},{"word":"item","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈaɪ.t̬əm/","meaning":"món đồ"}],"optionMeanings":["nó","its","của riêng nó","chính nó"]},{"questionNum":"103","question":"The Springly Energy marketing team is working hard ------- our latest products.","bilingual":"Đội ngũ tiếp thị Springly Energy đang làm việc chăm chỉ -------sản phẩm mới nhất của chúng tôi.","options":["promote","to promote","promoted","were promoting"],"correctIndex":1,"explanation":"Chỗ trống cần điền cấu trúc “to V” dùngđể chỉ mục đích. - promote (V): quảng bá, quảng cáo - to promote (to V): quảng bá, quảng cáo - promoted (V -ed): quảng bá, quảng cáo - werepromoting (V -qktd): quảng bá, quảngcáo *Cấu trúc: Latest: mới nhất. Dịch: Nhóm marketing của Springly Energy đang làm việc chăm chỉ ĐỂ QUẢNG BÁ sản phẩm mới nhất của chúng tôi.","vocabList":[{"word":"marketing","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/''mɑ:kitiɳ/","meaning":"tiếp thị"},{"word":"products","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈprɑdəkts/","meaning":"sản phẩm"},{"word":"promoted","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/prəˈmoʊtəd/","meaning":"được thăng chức"},{"word":"promote","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/prəˈmoʊt/","meaning":"thăng chức, thăng cấp; đề bạt"}],"optionMeanings":["quảng bá","để quảng bá","được thăng chức","đang quảng bá"]},{"questionNum":"104","question":"The job advertisement lists several ------- needed to apply for the position.","bilingual":"Bản tin tuyển dụng liệt kê một số ------- cần thiết để ứng tuyển vào vị trí này.","options":["specialists","qualifications","engagements","assortments"],"optionMeanings":["các chuyên gia","các tiêu chuẩn / bằng cấp chuyên môn","các cam kết, cuộc hẹn","các nhóm phân loại, mặt hàng hỗn hợp"],"correctIndex":1,"explanation":"Chỗ trống đứng sau ''several'' (một vài) cần một danh từ đếm được số nhiều làm tân ngữ cho động từ ''lists''.\n- specialists (N): các chuyên gia\n- qualifications (N): các tiêu chuẩn / bằng cấp chuyên môn\n- engagements (N): các cam kết, cuộc hẹn\n- assortments (N): các nhóm phân loại, mặt hàng hỗn hợp\n* Cấu trúc: several + N (đếm được số nhiều): một vài cái gì đó. Phù hợp nhất với ngữ cảnh mẩu tin tuyển dụng là ''qualifications'' (tiêu chuẩn chuyên môn / bằng cấp).\nDịch: Bản tin tuyển dụng liệt kê một vài TIÊU CHUẨN NĂNG LỰC / BẰNG CẤP cần thiết để ứng tuyển vào vị trí này.","vocabList":[{"word":"advertisement","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/æd.vɝːˈtaɪz.mənt/","meaning":"bản tin quảng cáo, tin tuyển dụng"},{"word":"qualification","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˌkwɒl.ɪ.fɪˈkeɪ.ʃən/","meaning":"phẩm chất, năng lực, bằng cấp chuyên môn"},{"word":"specialist","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈspeʃ.əl.ɪst/","meaning":"chuyên gia, chuyên viên"},{"word":"several","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ˈsev.ər.əl/","meaning":"vài, một số (đi với danh từ số nhiều)"},{"word":"list","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/lɪst/","meaning":"danh sách; liệt kê"}]},{"questionNum":"105","question":"When the contract is signed and received, it will become- ------- immediately.","bilingual":"Khi hợp đồng được ký và nhận, nó sẽ trở thành -------ngay lập tức.","options":["effective","effect","effected","effectively"],"correctIndex":0,"explanation":"Chỗ trống cần điền một tính từ đisau Linking V (become) để bổ sung ý nghĩa cho đại từ “it” phía trước. - effective (Adj): có hiệu lực, có hiệu quả - effect (N): hiệu lực - effected (V -ed): được thực hiện - effectively (Adv): một cách hiệu quả *Cấu trúc: Immediately (Adv): ngay lập tức. Dịch: Khi hợp đồng được kí và tiếp nhận, nó sẽ trở nên CÓ HIỆU LỰC ngay lập tức.","vocabList":[{"word":"effectively","pos":"Trạng từ (Adverb)","level":"Level 1: Dưới 200 đi","ipa":"/əˈfek.tɪv.li/","meaning":"có hiệu quả"},{"word":"effective","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/əˈfek.tɪv/","meaning":"hiệu quả, có hiệu lực"},{"word":"contract","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈkɑnˌtrækt/","meaning":"tạo ra một thỏa thuận chính thức; ràng buộc về mặt pháp lý; để có được"},{"word":"receive","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ri''si:v/","meaning":"nhận, lĩnh, thu"}],"optionMeanings":["hiệu quả","hiệu ứng","đã thực hiện","hiệu quả"]},{"questionNum":"106","question":"It is unlikely that a policy change could have ------- the financial challenge that the construction company faced.","bilingual":"Khó có khả năng xảy ra thay đổi chính sách ------thách thức tài chính mà công ty xây dựng phải đối mặt.","options":["shared","banned","forbidden","prevented"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án, chỗ trốngcần điền một động từ V - PII. - shared (V - PII): chia sẻ - banned (V - PII): cấm - forbidden (V - PII): cấm - prevented (V - PII): ngăn chặn *Cấu trúc: Unlikely (Adj): không chắc đúng, không chắc xảy raTo ban = to forbid = to prohibit (V): cấm. Dịch: Không chắcrằng sự thay đổi chính sáchcó thể đã NGĂN CHẶN được những khó khăn tài chính mà công ty xây dựng phải đối mặt","vocabList":[{"word":"construction","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/kənˈstrəkʃən/","meaning":"xây dựng; kết cấu; ngành xây dựng tòa nhà"},{"word":"financial","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/faɪˈnæn.ʃəl/","meaning":"/fəˈnæn.ʃəl/"},{"word":"challenge","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈʧælənʤ/","meaning":"hoàn cảnh khó khăn; một cái gì đó kiểm tra khả năng của một người"},{"word":"company","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈkʌm.pə.ni/","meaning":"công ty, bạn bè, bằng hữu"}],"optionMeanings":["được chia sẻ","bị cấm","bị cấm","ngăn chặn"]},{"questionNum":"107","question":"Barsan Photo is ------- that their latest printer will not be available before the start of the third quarter.","bilingual":"","options":["acknowledge","acknowledges","acknowledging","acknowledgement"],"correctIndex":2,"explanation":"Đáp án đúng là (C) \"acknowledging\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"available","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/əˈveɪ.lə.bəl/","meaning":"có sẵn để dùng"},{"word":"printer","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈprɪnər/","meaning":"thiết bị ngoại vi máy tính được sử dụng để xuất tài liệu sang"},{"word":"quarter","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/kˈwɔrtər/","meaning":"một phần tư; hàng xóm; đồng xu trị giá 25 xu; Giai đoạn"},{"word":"photo","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈfoʊˌtoʊ/","meaning":"hình ảnh; ảnh chụp nhanh"}]},{"questionNum":"108","question":"Thanks to the new system we installed, all lights and other devices turn on ------- when you enter the office.","bilingual":"Nhờ hệ thống mới được chúng tôi lắp đặt nên tất cả đèn và các thiết bị khác đều bật sáng ------khi bạn bước vào văn phòng.","options":["heavily","seriously","automatically","furiously"],"correctIndex":2,"explanation":"Đây là câu hỏi từ vựng cần dựa vào nghĩa và ngữ cảnh để chọn đáp án, chỗ trống cần điền một trạng từ để bổ sung ý nghĩa cho động từ “turn on” phía trước. - heavily (Adv): nặng nề - seriously (Adv): nghiêm túc - automatically (Adv): tự động - furiously (Adv): giận dữ *Cấu trúc: Thanks to + N: Nhờ có, nhờ vào Dịch: Nhờ có hệ thống mới được chúng tôi lắp đặt, tất cả đèn và các thiết bị khác bật lên một cách TỰ ĐỘNG khi bạn bước vào văn phòng.","vocabList":[{"word":"install","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ɪnˈstɑːl/","meaning":"cài đặt, tải xuống"},{"word":"system","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/ˈsɪstəm/","meaning":"sự kết hợp của những thứ hoặc bộ phận liên quan tạo thành một"},{"word":"device","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈvaɪs/","meaning":"thiết bị, máy móc"},{"word":"office","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈɔfəs/","meaning":"buồng; văn phòng; đương nhiệm; hãng; thẩm quyền"}],"optionMeanings":["rất nhiều","nghiêm túc","tự động","giận dữ"]},{"questionNum":"109","question":"------- the high demand for apartments, the study says single detachedhomeswill be the most popular dwelling in five years.","bilingual":"------Trước nhu cầu cao về căn hộ, nghiên cứu cho biết những ngôi nhà biệt lập sẽ là nơi ở phổ biến nhất trong 5 năm tới.","options":["Despite","Apparently","As expected","In contrast"],"correctIndex":0,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - Despite: Mặc dù - Apparently (Adv): hình như - As expected: như mongđợi - In contrast: Ngược lại *Cấu trúc: Despite + N = In spite of + N: Mặc dùAlthough + Mệnhđề = Though + Mệnhđề. Dịch: MẶC DÙ vẫn có nhu cầu cao đốivớicăn hộ, một nghiên cứu cho rằng những nhà riêngđơn lẻ vẫn là hình thức nhàở phổ biến nhất trong 5 năm tới.","vocabList":[{"word":"apartment","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/əˈpɑrtmənt/","meaning":"phẳng"},{"word":"expected","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/ɪkˈspɛktɪd/","meaning":"hy vọng"},{"word":"popular","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/ˈpɑːpjələr/","meaning":"được nhiều người ưa chuộng, được nhiều người"},{"word":"demand","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈmænd/","meaning":"sự đòi hỏi; yêu cầu"}],"optionMeanings":["Mặc dù","Rõ ràng","Như mong đợi","Ngược lại"]},{"questionNum":"110","question":"The process for estimating our yearly expenses is -------,so we can start planning staffing for next year.","bilingual":"Quá trình ước tính chi phí hàng năm của chúng tôi là ------, để chúng ta có thể bắt đầu lập kế hoạch nhân sự cho năm tới.","options":["careless","full","entire","complete"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án, chỗ trống cần điền một tính từ đi sau động từ “To be”. - C areless (Adj): bất cẩn - Full (Adj): đầy đủ - Entire (Adj): toàn bộ (D) complete - Complete (Adj): hoàn thành *Cấu trúc: Start + Ving: bắt đầu làm gì. Dịch: Quy trìnhước tính chi phí hàng năm của chúng ta đã HOÀN THÀNH, nên chúng ta có thể bắt đầu tuyển nhân viên và năm tới.","vocabList":[{"word":"expenses","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ɪkˈspɛnsɪz/","meaning":"Chi phí"},{"word":"complete","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/kəmˈpliːt/","meaning":"đầy đủ, hoàn thiện"},{"word":"process","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/''prouses/","meaning":"quá trình, sự tiến triển"},{"word":"entire","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ɪnˈtaɪər/","meaning":"trọn; bao gồm mọi phần; hoàn thành; đầy"}],"optionMeanings":["bất cẩn","đầy đủ","toàn bộ","hoàn thành - Hoàn thành (Adj): hoàn thành *Cấu trúc: Start + Ving: bắt đầu làm dịch vụ: Quy trình tính chi phí hàng năm của chúng ta đã HOÀN THÀNH, nên chúng ta có thể bắt đầu tuyển nhân viên và năm tới."]},{"questionNum":"111","question":"As of June 26, only one ------- had called to request space at the trade show.","bilingual":"Tính đến ngày 26 tháng 6, chỉ có một ------đã gọi đến không gian yêu cầu tại triển lãm thương mại.","options":["exhibitor","exhibit","exhibition","exhibiting"],"correctIndex":0,"explanation":"Chỗ trống cần điền một danh từlàm chủ ngữ trong câu, và cần một danh từ chỉ người để phù hợp với ngữ cảnh của câu. - Exhibitor (N): nhà tổ chức triển lãm - Exhibit (V): trưng bày - Exhibition (N): buổi triển lãm - Exhibiting (V - ing): trưng bày *Cấu trúc: As of + mốc thời gian: tínhđến ngày/tháng/năm…Dịch: Tính đến ngày 26/6, chỉ có duy nhất một NHÀ TỔ CHỨC TRIỂN LÃM gọi điện để yêu cầu đặt chỗ tại hội chợ.","vocabList":[{"word":"exhibition","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˌɛksəˈbɪʃən/","meaning":"trưng bày; trình diễn; trình bày trước công chúng về công việc hoặc kỹ năng;"},{"word":"request","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/rɪˈkwest/","meaning":"yêu cầu"},{"word":"exhibit","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ɪɡˈzɪb.ɪt/","meaning":"trưng bày, triển lãm"},{"word":"space","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 4: 400 - 495 đ","ipa":"/speɪs/","meaning":"vũ trụ; khu vực trống; khoảng cách; khu vực; khoảng thời gian"}],"optionMeanings":["nhà triển lãm","triển lãm","triển lãm","trưng bày"]},{"questionNum":"112","question":"To keep costs ------- an established budget, the owner decided to reduce the size of the garage to be constructed.","bilingual":"Để giữ chi phí ------Ngân sách đã được thiết lập, chủ sở hữu quyết định giảm bớt diện tích của gara để xây dựng.","options":["into","over","within","beside"],"correctIndex":2,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - into: vào trong - over: lên trên - w ithin: trong phạm vi - beside: bên cạnh *Cấu trúc: Decide to V: quyết định làm gì. Dịch: Để giữ chi phí TRONG KHOẢNG ngân sách cho trước, chủ thầu quyết định giảm quy mô xây dựng của garage.","vocabList":[{"word":"budget","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈbʌdʒ.ɪt/","meaning":"ngân sách; dự thảo ngân sách"},{"word":"decide","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˌdɪˈsaɪd/","meaning":"lựa chọn; để chọn từ một số tùy chọn; để kết luận;"},{"word":"reduce","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ri''dju:s/","meaning":"thu nhỏ, làm giảm bớt"},{"word":"within","pos":"Giới từ (Preposition)","level":"Level 4: 400 - 495 đ","ipa":"/wɪˈθɪn/","meaning":"trong thời gian"}],"optionMeanings":["vào","trên","trong vòng","bên cạnh"]},{"questionNum":"113","question":"The outdoor sales event was a great success- ------- the cold and rainy weather.","bilingual":"Sự kiện bán hàng ngoài trời đã thành công tốt đẹp ------thời tiết lạnh và mưa.","options":["in spite of","provided that","although","unless"],"correctIndex":0,"explanation":"Chỗ trống cần điền một liên từ để phù hợp về nghĩa và ngữ cảnh trong câu, liên từ phải đi kèm với danh từ / cụm danh từ đằng sau. - In spite of: mặc dù - Providedthat: với điều kiện là - Although: mặc dù - Unless: nếu không *Cấu trúc: In spite of + N = Despite + NAlthough + Mệnhđề = Though + MệnhđềProvided that + Mệnhđề = Providing that + MệnhđềUnless + Mệnhđề. Dịch: Sự kiện bán hàng ngoài trời đã thànhcông rực rỡ mặc dù thời tiết lạnh và có mưa.","vocabList":[{"word":"outdoor","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˈaʊtˌdɔr/","meaning":"của thiên nhiên"},{"word":"success","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/səkˈsɛs/","meaning":"đạt được điều gì đó mong muốn hoặc cố gắng;"},{"word":"weather","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈwɛðər/","meaning":"thời tiết"},{"word":"provide","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/prəˈvaɪd/","meaning":"cung cấp; cấp ; để thiết lập; cung cấp"}],"optionMeanings":["in default","với điều kiện là","mặc dù","trừ khi"]},{"questionNum":"114","question":"No ------- of Mr.Hanson''s book would be complete without mentioning his insightful analysis of the world of business blogs.","bilingual":"Không ------Cuốn sách của ông Hanson sẽ không đầy đủ nếu không đề cập đến phân tích sâu sắc của ông về thế giới blog kinh doanh.","options":["finish","summary","composition","organization"],"correctIndex":1,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chỗ trống cần điền danh từ để tạo thành cụm danh từ làm chủ ngữ. - Finish (N): đoạn cuối, phần kết thúc - Summary (N): bản tóm tắt - Composition (N): thành phần cấu tạo - Organization (N): tổ chức * Cấu trúc: Insightful (Adj): sâu sắc. Dịch: Không có bất cứ BẢN TÓM TẮT nào vềnội dung cuốn sách của Hanson được coi là hoàn thiện nếu khôngđề cập đến sự phân tích sâu sắc của anhấy về thế giới của những blog doanh nghiệp.","vocabList":[{"word":"organization","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/,ɔ:gənai''zeiʃn/","meaning":"sự tổ chức, sự cấu tạo"},{"word":"complete","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/kəmˈpliːt/","meaning":"đầy đủ, hoàn thiện"},{"word":"analysis","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/əˈnæl.ə.sɪs/","meaning":"sự phân tích, bản phân tích"},{"word":"business","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈbɪznɪs/","meaning":"công ty; doanh nghiệp; buôn bán; thương mại; vấn đề"}],"optionMeanings":["kết thúc","bản tóm tắt","thành phần","tổ chức"]},{"questionNum":"115","question":"Updating the product line that buyers have complained about will send an obvious ------- to our valued customers.","bilingual":"Cập nhật dòng sản phẩm người mua đã phàn nàn sẽ gửi một thông báo rõ ràng ------ tới quý khách hàng.","options":["messaging","messenger","message","messaged"],"correctIndex":2,"explanation":"Chỗ trống cần điền một danh từ để tạo thành cụm danh từ làm tân ngữ trong câu và cần một danh từ chỉ sự vật để phùhợp với ngữ cảnh trong câu. - Messaging (V - ing): gửi tin nhắn - Messenger (N): người đưa tin - Message (N): tin nhắn, thôngđiệp - Messaged (V - ed): gửi tin nhắn *Cấu trúc: Complain about + N: phàn nàn về điều gìSend sth to sbd: gửi cái gì đó cho ai","vocabList":[{"word":"complain","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/kəmˈpleɪn/","meaning":"kêu ca, phàn nàn, oán trách"},{"word":"customer","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈkʌs.tə.mɚ/","meaning":"khách hàng"},{"word":"product","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈprɑdəkt/","meaning":"kết quả sản xuất; hàng hóa; hàng hóa"},{"word":"message","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/ˈmɛsɪʤ/","meaning":"giao tiếp; thông tin; thông báo; ghi chú;"}],"optionMeanings":["nhắn tin","Messenger","tin nhắn","đã nhắn tin"]},{"questionNum":"116","question":"The Internet will ------- bea crucial part of the economy for the foreseeable future.","bilingual":"Internet sẽ ------là một phần quan trọng của nền kinh tế trong tương lai gần.","options":["concisely","perfectly","currently","undoubtedly"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chỗ trống cần điền một trạnh từ bổ sung ý nghĩa cho cụm danh từ “a crucial part”. - C oncisely (Adv): chính xác (về mặt số liệu) - Perfectly (Adv): một cách hoàn hảo (D) undoubtedly - Currently (Adv): hiện nay - Undoubtedly (Adv): chắc chắn *Cấu trúc: Crucial (Adj): thiết yếuForeseeable (Adj): có thể đoán trước. Dịch: Internet CHẮC CHẮN sẽ là 1 phần thiết yếu của nền kinh tế trong tương lai gần.","vocabList":[{"word":"currently","pos":"Trạng từ (Adverb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈkərəntli/","meaning":"hiện tại"},{"word":"internet","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈɪntərˌnɛt/","meaning":"Internet"},{"word":"economy","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/iˈkɑː.nə.mi/","meaning":"nền kinh tế"},{"word":"future","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/fˈjuʧər/","meaning":"tương lai"}],"optionMeanings":["chính xác","hoàn hảo","hiện tại","chắc chắn - Hiện tại (Adv): hiện nay - Chắc chắn rồi (Adv): chắc chắn *Cấu trúc: Crucial (Adj): thiết yếuCó thể thấy trước (Adj): có thể đoán trướcdịch: Internet CHẮC CHẮN sẽ là 1 phần thiết yếu của nền kinh tế trong tương lai gần."]},{"questionNum":"117","question":"The man agement team required little ------- before deciding to promote Ms. Yang.","bilingual":"","options":["deliberation","deliberate","deliberated","deliberately"],"correctIndex":0,"explanation":"Đáp án đúng là (A) \"deliberation\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"required","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/rikˈwaɪərd/","meaning":"bắt buộc"},{"word":"promote","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/prəˈmoʊt/","meaning":"thăng chức, thăng cấp; đề bạt"}]},{"questionNum":"118","question":"The human resources office is adopting a more ------- policy that would give employees additional vacation days.","bilingual":"Văn phòng nhân sự đang áp dụng thêm ------ chính sách cho phép nhân viên có thêm ngày nghỉ phép.","options":["generous","collaborative","severe","regional"],"correctIndex":0,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chỗ trống cần điền một tính từ để tạo thành cụm danh từ làm tân ngữ. - generous (Adj): rộng lượng, hào phóng - collaborative (Adj): cộng tác, hợptác - severe (Adj): khắt khe, gay gắt - regional (Adj): thuộc vùng, địa phương *Cấu trúc: Adopt (V): thực hiện. Dịch: Văn phòng nhân sự đang thực hiện một chính sách HÀO PHÓNG hơn, cho phép nhân viên được có thêm ngày nghỉ.","vocabList":[{"word":"additional","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/əˈdɪʃ.ən.əl/","meaning":"thêm vào, phụ thêm"},{"word":"resource","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/ˈrisɔrs/","meaning":"cung cấp; Cổ phần; phương tiện để hoàn thành mục tiêu;"},{"word":"employee","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ɪmˈplɔɪi/","meaning":"công nhân; người làm việc cho một công ty hoặc một"},{"word":"vacation","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/veɪˈkeɪ.ʃən/","meaning":"kì nghỉ"}],"optionMeanings":["hào phóng","hợp tác","nghiêm trọng","khu vực"]},{"questionNum":"119","question":"Mr.Greaves will speak to our suppliers about ------- handling of the transportation situation.","bilingual":"Ông Greaves sẽ nói chuyện với các nhà cung cấp của chúng tôi về ------xử lý tình huống vận chuyển.","options":["they","their","them","these"],"correctIndex":1,"explanation":"Chỗ trống cần điền một tính từ sởhữu bổ sung ý nghĩa cho cụm danh từ phía sau làm tân ngữ trong câu. - They (Đại từ làm chủ ngữ) - Their (Tính từ sở hữu) - Them (Đại từ làm tân ngữ) (C) them(D) these - These (Chỉ định từ) *Cấu trúc: Tính từ sở hữu + Danhđộng từ (V - ing) Speak to sb about sth: Nói với ai đó về điềugì. Dịch: Ông Greaves sẽ nói với nhà cung cấp của chúng ta về việc xử lý tình hình vận chuyển CỦA HỌ.","vocabList":[{"word":"transportation","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˌtræn.spɚˈteɪ.ʃən/","meaning":"sự vận chuyển"},{"word":"situation","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˌsɪtʃ.uˈeɪ.ʃən/","meaning":"tình hình"},{"word":"supplier","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/səˈplaɪ.ɚ/","meaning":"nhà cung cấp"}],"optionMeanings":["họ","Giải thích của họ: Chỗ trống cần điền một tính từ sở hữu bổ sung sung ý nghĩa cho cụm danh từ sau làm tân ngữ trong câu. - They (Đại từ làm chủ ngữ) - their ( Tính từ sở hữu) - Họ (Đại từ làm tân ngữ)","chúng","những cái này - Cái này (Chỉ định từ) *Cấu trúc: Tính từ sở hữu + Danh động từ (V - ing) Nói chuyện với sb về sth: Nói với ai đó về điềugì dịch: Ông Greaves sẽ nói với nhà cung cấp của chúng ta về công việc xử lý tình hình vận chuyển của HỌ."]},{"questionNum":"120","question":"This is only a preliminary list of job candidates, so interviewers should ------- the possibility of last - minute additions.","bilingual":"Đây chỉ là danh sách sơ bộ các ứng viên nên người phỏng vấn nên ------khả năng cuối cùng - phút bổ sung.","options":["wait","decide","expect","figure"],"correctIndex":2,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chõ trống cần điền một động từ nguyên thể (V) đi sau động từ khuyết thiếu “Should” - wait (V) + for: Chờ đợi - decide (V) + to V: quyết định - expect (V): mongđợi - figure (V) + out: nhận ra *Cấu trúc: Should + V = Had better + V: nên làm gìInterviewer: người hỏi trong buổi phỏng vấn (nhà tuyển dụng)Interviewee: người trả lời trong buổi phỏng vấn (ứng viên)Dịch: Đây chỉ là danh sáchứng viên xin việc sơ bộ, vì vậy người phỏng vấn nên MONG ĐỢI vào khả năng sẽ có thêm sự bổ sung vào phút chót.","vocabList":[{"word":"candidate","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈkæn.dɪ.dət/","meaning":"/ˈkæn.dɪ.deɪt/"},{"word":"addition","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/əˈdɪʃən/","meaning":"bổ sung; phép toán"},{"word":"minute","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈmɪnət/","meaning":"đơn vị thời gian bằng 60 giây; 1/60 của một giờ;"},{"word":"decide","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˌdɪˈsaɪd/","meaning":"lựa chọn; để chọn từ một số tùy chọn; để kết luận;"}],"optionMeanings":["chờ","quyết định","mong đợi","figure"]},{"questionNum":"121","question":"Market conditions were ------- enough last year for us to make several new acquisitions.","bilingual":"Điều kiện thị trường là ------năm ngoái đã đủ để chúng tôi thực hiện một số vụ mua lại mới.","options":["favor","favorite","favorably","favorable"],"correctIndex":3,"explanation":"Chỗ trống cần điền một tính từphù hợp với cấu trúc “Adj + enough”. - favor (N): thiệný - fa vorite (Adj): yêu thích - favorably (Adv): có lợi - favorable (Adj): có lợi *Cấu trúc: Enough + ADJ: đủ như thế nàoN + Enough: đủ cái gì. Dịch: Tình hình thị trường năm ngoái đủ CÓ LỢI cho chúng ta để thực hiện nhiều cuộc mua lại.","vocabList":[{"word":"acquisition","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˌækwəˈzɪʃən/","meaning":"mua; thứ gì đó đã được mua hoặc"},{"word":"conditions","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/kənˈdɪʃənz/","meaning":"điều kiện"},{"word":"favorable","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˈfeɪvərəbəl/","meaning":"tích cực; phê duyệt; như nhau; hữu ích; khuyến khích;"},{"word":"favorite","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˈfeɪvərɪt/","meaning":"ưa thích; yêu quý; thích"}],"optionMeanings":["ủng ​​hộ","yêu thích","thuận lợi","thuận lợi"]},{"questionNum":"122","question":"Web advertising is smart in the sense that it can be highly specific and target a market ------- great accuracy.","bilingual":"Quảng cáo trên web thông minh theo nghĩa là nó có thể rất cụ thể và nhắm mục tiêu vào một thị trường -","options":["near","during","between","with"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - near: gần -------great accuracy. (A) near(B) during(C) between(D) with - during: trong suốt - between: giữa - with: với *Cấu trúc: In the sense that: theo cách nào đó/bằngcách nào đó/ở khía cạnh nào đó. Dịch: Quảng cáo trên web thông minh trong khía cạnh nó có độ chi tiết cao và nhắm mục tiêu vào thị trường VỚI độ chính xác cao.","vocabList":[{"word":"advertising","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈædvərˌtaɪzɪŋ/","meaning":"Quảng cáo"},{"word":"highly","pos":"Trạng từ (Adverb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈhaɪ.li/","meaning":"rất, lắm, tốt"},{"word":"target","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 4: 400 - 495 đ","ipa":"/ˈtərgət/","meaning":"đánh dấu; khách quan; mục tiêu; sự vật; mục tiêu"},{"word":"market","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/ˈmɑrkɪt/","meaning":"nhu cầu về hàng hóa hoặc dịch vụ; tỷ lệ mua hàng và"}],"optionMeanings":["gần","trong thời gian","giữa","kèm theo - trong thời gian: trong suốt - giữa: giữa - với: with *Cấu trúc: Theo nghĩa: theo cách nào đó/bằng cách nào đó/mở khía cạnh nào đó Dịch vụ: Quảng cáo trên web thông minh trong khía cạnh có độ chi tiết cao và ngọc mục vào thị trường hoàn toàn chính xác cao."]},{"questionNum":"123","question":"The library director requests that staff obtain-. ------- in instructional technology to better support the library''s educational programs.","bilingual":"Giám đốc thư viện yêu cầu nhân viên nhận được -------- về công nghệ giảng dạy để hỗ trợ tốt hơn cho các chương trình giáo dục của thư viện.","options":["certification","certified","certifiable","certifier"],"correctIndex":0,"explanation":"Chỗ trống cần điền một danh từlàm tân ngữ và cần danh từ chỉ sự vật để phùhợp với ngữ cảnh trong câu. - certification (N): chứng chỉ - certified (V - ed): chứng nhận - certifiable (Adj): có thể chứng nhận - certifier (N): người chứng nhận","vocabList":[{"word":"educational","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˌɛʤəˈkeɪʃənəl/","meaning":"giáo dục"},{"word":"technology","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/tɛkˈnɑləʤi/","meaning":"khoa học nghệ thuật công nghiệp; khoa học ứng dụng"},{"word":"director","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/daɪˈrek.tɚ/","meaning":"/dɪˈrek.tɚ/"},{"word":"library","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈlaɪbrɛˌri/","meaning":"nơi mà người ta có thể mượn sách"}],"optionMeanings":["chứng nhận","được chứng nhận","có thể chứng nhận","người chứng nhận"]},{"questionNum":"124","question":"------- existing products, which are designed for people with technical expertise, this new program should appeal to a wider audience.","bilingual":"--------Các sản phẩm hiện có được thiết kế dành cho những người có chuyên môn kỹ thuật, chương trình mới này sẽ thu hút được nhiều đối tượng hơn.","options":["Before","Instead of","Unlike","While"],"correctIndex":2,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - Before: trước khi - Instead of: thay vì - Unlike: không giống như - While: trong khi *Cấu trúc: Appealto + N: thu hút, hấp dẫn","vocabList":[{"word":"technical","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ˈtek.nɪ.kəl/","meaning":"có tính kỹ thuật"},{"word":"existing","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/ɪgˈzɪstɪŋ/","meaning":"hiện có"},{"word":"products","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈprɑdəkts/","meaning":"sản phẩm"},{"word":"audience","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈɑː.di.əns/","meaning":"khán thính giả"}],"optionMeanings":["Trước","Thay vì","Không giống như","Trong khi"]},{"questionNum":"125","question":"Some functions of our Web team are to identify problems with applications and then ------- fixes.","bilingual":"Một số chức năng của nhóm Web của chúng tôi là xác định các vấn đề với ứng dụng và sau đó --------sửa lỗi.","options":["priority","prioritize","prioritized","prioritization"],"correctIndex":1,"explanation":"Chỗ trống cần điền một động từcó cùng cấu trúc ngữ pháp với động từ “identify” vì có liên từ đẳng lập “and” - priority (N): sựưu tiên - prioritize (V): ưu tiên - prioritized (V - ed): ưu tiên - prioritization (N): sự sắp xếp dựa trên sựưutiên *Cấu trúc: Identify (V): xác định. Dịch: Một số chức năng của nhóm quản lýtrang Web của chúng ta là xác định vấn đề xảy ra vớiứng dụng và ƯU TIÊN khắc phục lỗingay lập tức.","vocabList":[{"word":"application","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˌæp.ləˈkeɪ.ʃən/","meaning":"ứng dụng, sự áp dụng"},{"word":"function","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈfʌŋk.ʃən/","meaning":"hoạt động; chức năng"}],"optionMeanings":["ưu tiên","ưu tiên","được ưu tiên","ưu tiên"]},{"questionNum":"126","question":"This partnership ------- a great opportunity for us at Stolant Tech to broaden our inventory of available software.","bilingual":"Sự hợp tác này --------một cơ hội tuyệt vời để chúng tôi tại Stolant Tech mở rộng kho phần mềm có sẵn của chúng tôi.","options":["corresponds","represents","appreciates","intends"],"correctIndex":1,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chỗ trống cần điền một động từ làm động từ chính trong câu, và chia theo chủ ngữ sốít “partnership” phía trước. - corresponds (V -s) + with: phù hợp, tươngthích - represents (V -s): thể hiện, cho thấy - appreciates (V - s) + Ving: đánh giá cao - intends (V - s) + to V: dự định *Cấu trúc: Broaden (V): mở rộngInventory (N): danh mục hàng tồn kho. Dịch: Sự hợp tác lần này CHO THẤY một cơ hội lớn đối với chúng ta tại Stolant Tech nhằm mở rộng danh mục các phần mềm sẵn có của chúng ta.","vocabList":[{"word":"partnership","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/ˈpɑːrtnərʃɪp/","meaning":"quan hệ đối tác, sự hợp tác"},{"word":"opportunity","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ɒpərˈtyunɪti/","meaning":"cơ hội, thời cơ, dịp may"},{"word":"appreciate","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/əˈpriː.ʃi.eɪt/","meaning":"đánh giá cao, cảm kích"},{"word":"inventory","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈɪn.vən.tɔːr.i/","meaning":"sự kiểm kê, bản kiểm kê"}],"optionMeanings":["tương ứng","đại diện cho","đánh giá cao","dự định"]},{"questionNum":"127","question":"We will need to delay the start of the advertising campaign because the relevant contracts have only been ------- completed.","bilingual":"Chúng tôi sẽ cần trì hoãn việc bắt đầu chiến dịch quảng cáo vì các hợp đồng liên quan chỉ mới được ký kết --------hoàn thành.","options":["part","parted","partial","partially"],"correctIndex":3,"explanation":"Chỗ trống cần điền một trạnh từ để bổ sung ý nghĩa cho V - PII “completed” phía sau. - part (N): một phần, (V): tách ra - parted (V - ed): tách ra - partial (Adj): một phần - partially (Adv): một phần","vocabList":[{"word":"advertising","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈædvərˌtaɪzɪŋ/","meaning":"Quảng cáo"},{"word":"completed","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/kəmˈplitɪd/","meaning":"đã hoàn thành"},{"word":"campaign","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/kæmˈpeɪn/","meaning":"chiến dịch, cuộc vận động"},{"word":"contract","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈkɑnˌtrækt/","meaning":"tạo ra một thỏa thuận chính thức; ràng buộc về mặt pháp lý; để có được"}],"optionMeanings":["phần","chia tay","một phần","một phần"]},{"questionNum":"128","question":"------- much of the accounting staff will be on vacation next week, the ones remaining in the office will be very busy.","bilingual":"--------phần lớn nhân viên kế toán sẽ đi nghỉ vào tuần tới, những người còn lại ở văn phòng sẽ rất bận rộn.","options":["Until","Except for","Because","Due to"],"correctIndex":2,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - Until: cho đến khi - Exceptfor + N: trừ khi - Because + Mệnhđề: bởi vì - Due to + N: bởi vì *Cấu trúc: (C) Because(D) Due to","vocabList":[{"word":"accounting","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/əˈkaʊn.t̬ɪŋ/","meaning":"sự tính toán, thanh toán"},{"word":"vacation","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/veɪˈkeɪ.ʃən/","meaning":"kì nghỉ"},{"word":"remain","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/rɪˈmeɪn/","meaning":"duy trì"},{"word":"office","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈɔfəs/","meaning":"buồng; văn phòng; đương nhiệm; hãng; thẩm quyền"}],"optionMeanings":["Cho đến","Ngoại trừ","Bởi vì","Do Dịch: BỞI VÌ phần lớn nhân viên kế toán sẽ được nghỉ vào tuần tới, những người còn lại trong văn phòng sẽ rất bận rộn."]},{"questionNum":"129","question":"------- sendingmultiplee-mails to share ideas and reach a decision, the team leader called a one-hour meeting to discuss the issue.","bilingual":"--------gửi nhiều thư để chia sẻ ý tưởng và đi đến quyết định, trưởng nhóm gọi một thư - họp hàng giờ để thảo luận vấn đề.","options":["As a result","In order to","The same as","Rather than"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. - As a result: Vì vậy, kết quả là - In order to + V: để làm gì - The same as + N: giống với - Rather than + Ving/N: thay vì *Cấu trúc: In order to + V = So as to + V: để làm gì. Dịch: THAY VÌ gửi nhiều e - mailđể chia sẻýtưởng và điđến quyết định, trưởng nhóm đãtổ chức một cuộc họp kéo dài một giờ để thảo luận về vấn đề này.","vocabList":[{"word":"decision","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈsɪʒ.ən/","meaning":"quyết định"},{"word":"meeting","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/''mi:tiɳ/","meaning":"(chính trị) cuộc mít tinh, cuộc biểu tình"},{"word":"discuss","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈskʌs/","meaning":"thảo luận, tranh luận"},{"word":"leader","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈlidər/","meaning":"cái đầu; trưởng; giám đốc; người vận chuyển; bài viết chính"}],"optionMeanings":["Kết quả là","Để","Điều tương tự như","Thay vì"]},{"questionNum":"130","question":"Applicants for the position of flight attendant at Joyous Airlines need to ------- a calm sense of authority at all times.","bilingual":"Ứng viên cho vị trí tiếp viên hàng không tại JoyousAirlines cần -------một cảm giác bình tĩnh của quyền lực mọi lúc.","options":["estimate","appear","involve","project"],"correctIndex":3,"explanation":"Đây là câu hỏi từ vựng nên cầndựa vào nghĩa và ngữ cảnh để chọn đáp án. Chỗ trống cần điền một động từ nguyên thể để phù hợp với cấu trúc “Need + to V”. - estimate (V): ước tính - appear (V): xuất hiện - involve (V): bao gồm - project (V): thể hiện ra *Cấu trúc: Need to V: cần làm gìAuthority (N): chuyên môn, thẩm quyền. Dịch: Cácứng viênứng tuyển cho vị trí tiếp viên hàng không tại Joyous Airlines cần phải luôn luôn THỂ HIỆN chuyên môn của mình một cách bình tĩnh. PART 6","vocabList":[{"word":"applicant","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈæp.lə.kənt/","meaning":"người ứng tuyển, nguyên cáo"},{"word":"authority","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/əˈθɔːr.ə.t̬i/","meaning":"quyền thế, nhà chức trách, chính quyền"},{"word":"position","pos":"Verb (Động từ)","level":"B1","ipa":"/pəˈzɪʃn/","meaning":"đặt vào vị trí"},{"word":"estimate","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈes.tə.meɪt/","meaning":"ước tính, dự đoán"}],"optionMeanings":["ước tính","xuất hiện","liên quan đến","dự án"]}]'::jsonb,
