-- Card 22: p5-ets2023-test-9 (ETS 2023 Test 9 - Part 5)
INSERT INTO reading_exercise_cards (
    id, title, category, sub_category, subtitle, tag,
    total_questions, passage_text, passage_text_vi,
    passages, theory, sample_questions, order_index, created_at, updated_at
) VALUES (
    'p5-ets2023-test-9',
    'ETS 2023 Test 9 - Part 5',
    'part5',
    'levels',
    '30 câu hỏi ngữ pháp & từ vựng chuẩn đề ETS 2023 Test 9',
    'ETS 2023 · Test 9',
    30,
    NULL,
    NULL,
    '[]'::jsonb,
    '{"summary":"Toàn bộ 30 câu hỏi Part 5 chuẩn đề thi ETS 2023 Test 9, bao gồm kiểm tra từ loại, thì, liên từ và từ vựng ngữ cảnh.","rules":["Xác định từ loại và cấu trúc chỗ trống trước khi đọc cả câu.","Loại trừ các phương án sai thì, sai hòa hợp chủ vị hoặc sai giới từ đi kèm."],"example":"Edison Delivery''s trucks leave the warehouse promptly ------- 6:00 A.M. each morning."}'::jsonb,
    '[{"questionNum":"101","question":"Edison Delivery''s trucks leave the warehouse promptly ------- 6:00 A.M. each morning.","bilingual":"Xe của Edison Delivery rời kho ngay-------6 giờ sáng mỗi buổi sáng.","options":["at","on","for","with"],"correctIndex":0,"explanation":"Chỗ trống cần điền một giới từ chỉthời gian đi kèm với thời gian cụ thể - at + mốc thời gian cụthể như giờ giấctrong ngày, hoặc cụm từ chỉ thời gian chứa time, moment - on + khoảng thời gian cụ thể như tuần, ngày tháng, ngày lễ chứa Day - for + khoảng thời gian dài: thế kỷ, năm, mùa… - with: giới từ chỉ cách thức: cùng, với (đi kèmvới N)*Cấu trúc: Warehouse: kho hàng, nhà khoPromptly = punctually: nhanh chóng, đúnggiờ. Dịch: Các xe tải của Vận chuyển Edison rời nhà kho MỘT CÁCH ĐÚNG GIỜ vào 6 giờ mỗi buổi sáng","vocabList":[{"word":"warehouse","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈwer.haʊs/","meaning":"kho hàng"},{"word":"delivery","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈlɪv.ɚ.i/","meaning":"sự phân phát, giao hàng"},{"word":"promptly","pos":"Trạng từ (Adverb)","level":"Level 1: Dưới 200 đi","ipa":"/´prɔmptli/","meaning":"mau lẹ, nhanh chóng; ngay lập tức"},{"word":"leave","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/liv/","meaning":"khởi hành; để thoát ra; bỏ cuộc; bỏ qua; để yên"}],"optionMeanings":["tại","trên","cho","với"]},{"questionNum":"102","question":"A ------- copy of the rental agreement for the apartment has been delivered to the main office.","bilingual":"A -------bản sao hợp đồng thuê căn hộ đã được chuyển đến văn phòng chính.","options":["signature","sign","signs","signed"],"correctIndex":3,"explanation":"Chỗ trống cần điền 1 tính từ để bổ sung nghĩa cho danh từ “copy” - signature (N): chữ ký - sign (N): ký hiệu, dấu hiệu; (V): ký tên, ra hiệu - signs (Ns): các ký hiệu, các dấu hiệu - signed (V_ed): được ký, ngoài ra còn là tính động từ mang chức năng của tính từ *Cấu trúc: - A signed copy = A copy is signed: bản copy đãđược ký (bị động Vpii) - rental agreement: hợp đồng thuê. Dịch: Một bản sao hợp đồng thuê căn hộ CÓ CHỮ KÝ đãđược chuyển đến văn phòngchính","vocabList":[{"word":"agreement","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/əˈɡriː.mənt/","meaning":"hợp đồng, giao kèo"},{"word":"apartment","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/əˈpɑrtmənt/","meaning":"phẳng"},{"word":"deliver","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈlɪv.ɚ/","meaning":"phân phối, giao hàng, đem tới"},{"word":"rental","pos":"Tính từ (Adjective)","level":"Level 4: 400 - 495 đ","ipa":"/ˈrɛntəl/","meaning":"có sẵn để cho thuê hoặc cho thuê"}],"optionMeanings":["chữ ký","ký","dấu hiệu","đã ký"]},{"questionNum":"103","question":"------- can be made online or by calling customerservicebetween6:30 A.M. and 5:30 P.M.","bilingual":"-------có thể được thực hiện trực tuyến hoặc bằng cách gọi tới bộ phận dịch vụ khách hàng trong khoảng thời gian từ 6:30 sáng. và 5:30 chiều","options":["Reserve","Reserved","Reservations","Reservable"],"correctIndex":2,"explanation":"Chỗ trống cần điền một danh từ để làm chủ ngữ trong câu - Reserve (V): đặt trước, (N): sự dự trữ, khubảo tồn - Reserved (V_ed): đã được đặt trước - Reservations (Ns): sự đặt chỗ trước - Reservable (Adj): có thể đặt chỗ trước (D) Reservable *Cấu trúc: - customer service: dịch vụ khách hàng. Dịch: VIỆC ĐẶT TRƯỚC có thể được thực hiện trực tuyến hoặc bằng cách gọi cho dịch vụ khách hàng từ 6h30 sángđến 5h30 chiều","vocabList":[{"word":"reservation","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˌrez.ɚˈveɪ.ʃən/","meaning":"dự phòng"},{"word":"call","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/kɔl/","meaning":"mời; nói to; đến thăm; gọi điện thoại"}],"optionMeanings":["Dự trữ","Bảo ​​lưu","Đặt chỗ","Có thể đặt trước *Cấu trúc: - dịch vụ khách hàng: dịch vụ khách hàng Dịch hàng: VIỆC ĐẶT TRƯỚC có thể thực hiện tuyến tính hoặc bằng cách gọi cho dịch vụ khách hàng từ 6h30 sáng đến 5h30 chiều"]},{"questionNum":"104","question":"Ms.Shimabukurorosethroughtheranks ------- and became the manager in less than two years.","bilingual":"Cô Shimabukuro đã thăng hạng -------và trở thành người quản lý trong vòng chưa đầy hai năm.","options":["quick","quicken","quickly","quickening"],"correctIndex":2,"explanation":"Chỗ trống cần điền một trạng từ để bổ sung nghĩa cho động từ “rose - rise” - quick (Adj): nhanh - quicken (N): làm tăng nhanh, đẩy mạnh - quickly (Adv): một cách nhanh chóng - quickening (V_ing): đangđẩy mạnh *Cấu trúc: - less than + N: ít hơn cái gì - rise through therank: thăng cấp","vocabList":[{"word":"manager","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈmænɪʤər/","meaning":"người điều hành một công ty; giám đốc; quản trị viên;"},{"word":"quick","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/kwɪk/","meaning":"nhanh chóng"},{"word":"less","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/lɛs/","meaning":"ít hơn"}],"optionMeanings":["nhanh chóng","quicken","nhanh chóng","tăng tốc"]},{"questionNum":"105","question":"The Highland Museum of Robotics will be ------- for renovations until further notice.","bilingual":"Bảo tàng Robot Tây Nguyên sẽ -------để cải tạo cho đến khi có thông báo mới.","options":["bought","closed","stopped","held"],"correctIndex":1,"explanation":"Đây là một câu từ vựng nên cầndựa vào nghĩa để chọn đáp án đúng. - bought (V_pII): được mua – buy - closed (V_ed): bị đóng – close - stopped (V_ed): bị dừng – stop - held (V_pII): được tổ chức – hold *Cấu trúc: - renovation (N): sự sửa chữa lại - furth er: thêm nữa - notice = notification: thông báo. Dịch: Bảo tàng người máy Highland sẽ ĐƯỢC ĐÓNG CỬA cho việc sửa chữa cho đến khi có thông báo thêm.","vocabList":[{"word":"renovation","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˌren.əˈveɪ.ʃən/","meaning":"sự nâng cấp, sự cải tiến"},{"word":"museum","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/mˈjuziəm/","meaning":"viện bảo tàng"},{"word":"close","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/kloʊz/","meaning":"gần đó"}],"optionMeanings":["đã mua","đã đóng cửa","đã dừng lại","tổ chức"]},{"questionNum":"106","question":"The Hollytown Aren a designates an area where fans can meet their ------- athletes after each game.","bilingual":"","options":["favorite","favoritism","favorites","favoring"],"correctIndex":0,"explanation":"Đáp án đúng là (A) \"favorite\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"favorite","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˈfeɪvərɪt/","meaning":"ưa thích; yêu quý; thích"},{"word":"area","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈer.i.ə/","meaning":"khu vực, lĩnh vực, diện tích"}]},{"questionNum":"107","question":"Billboards that advertise legal services are most effective when placed ------- business districts.","bilingual":"Biển quảng cáo dịch vụ pháp lý sẽ hiệu quả nhất khi được đặt -------các khu kinh doanh.","options":["from","down","of","in"],"correctIndex":3,"explanation":"Trong câu này chúng ta cần điền 1 giới từ chỉ nơi chốn để tạo thành cụm danh từ chỉ địa điểm. - from + N: từ đâu - down: xuống, ở dưới - of + N: của cái gì - in + N: tại nơi nào *Cấu trúc: - billboard (n): biển quảng cáo -advertise (v): quảng cáo => advertisement (n) - legal(a): pháp lý, hợp pháp illegal(a): bất hợp pháp. Dịch: Biển quảng cáodịch vụ pháp lý có hiệuquả nhất khi được đặt TẠI các khu kinh doanh","vocabList":[{"word":"advertise","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈæd.vɚ.taɪz/","meaning":"quảng cáo, thông báo"},{"word":"effective","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/əˈfek.tɪv/","meaning":"hiệu quả, có hiệu lực"},{"word":"business","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈbɪznɪs/","meaning":"công ty; doanh nghiệp; buôn bán; thương mại; vấn đề"},{"word":"service","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/''sə:vis/","meaning":"sự phục vụ, sự hầu hạ"}],"optionMeanings":["từ","xuống","của","trong"]},{"questionNum":"108","question":"Ms.Uedawasquite ------- with the wholesale prices offered by Rea''s International Restaurant Suppliers.","bilingual":"Cô Ueda khá là ------- với giá bán buôn được cung cấp bởi Nhà cung cấp Nhà hàng Quốc tế của Rea.","options":["advised","true","pleased","strong"],"correctIndex":2,"explanation":"Trong câu này chúngta cần điền một tính từ, vì phía trước có linking V, dùngđể bổ nghĩa cho chủ ngữ. Các từ trongđáp án đều là tính từ, nên cần dựa vào nghĩa để chọn - advised (Adj): am hiểu, thận trọng - true (Adj): đúngđắn - pleased (Adj): hài lòng - strong (Adj): mạnhmẽ *Cấu trúc: - quite (Adv): khá - wholesale price (N): giá sỉ, giá bán buôn - offer (V): đưa ra, mời Dịch: Bà Ueda khá HÀI LÒNG với mức giá sỉmà Rea’s International Restaurant Suppliersđưa ra","vocabList":[{"word":"international","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/ˌɪn.t̬ɚˈnæʃ.ən.əl/","meaning":"quốc tế, đa quốc gia"},{"word":"restaurant","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈrɛˌstrɑnt/","meaning":"Nhà hàng"},{"word":"supplier","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/səˈplaɪ.ɚ/","meaning":"nhà cung cấp"},{"word":"pleased","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/plizd/","meaning":"nội dung; no; được thỏa mãn mong muốn của mình"}],"optionMeanings":["khuyên","ĐÚNG VẬY","hài lòng","mạnh mẽ"]},{"questionNum":"109","question":"Geology Monthly is a professional journal with articles written ------- for experts in the field.","bilingual":"Địa chất hàng tháng là một tạp chí chuyên nghiệp với các bài báo được viết -------chuyên gia ngoại hối trong lĩnh vực này.","options":["specify","had specified","specifics","specifically"],"correctIndex":3,"explanation":"Trong câu này chúng ta cần điền một trạng từ để bổ sung nghĩa cho động từ. “Các bài báo được viết như thế nào” - specify (V): chỉ rõ - h ad specified: sử dụng trong câu quá khứ (A) specify(B) had specified(C) specifics(D) specificallyhoàn thành - specifics (Ns): các chi tiết - specifically (Adv): một cách cụ thể *Cấu trúc: - professional (Adj): chuyên nghiệp - journal (N): nhật báo, tạp chí - article (N): bài báo, đồ dùng. Dịch: Geology Monthlylà một tạp chí chuyênngành với các bài báo được viết DÀNH RIÊNG cho các chuyên gia trong lĩnh vực.","vocabList":[{"word":"professional","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/prə''feʃənl/","meaning":"(thuộc) nghề, (thuộc) nghề nghiệp; có tay nghề"},{"word":"monthly","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈmənθli/","meaning":"hàng tháng"},{"word":"journal","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈdʒɝː.nəl/","meaning":"báo, tạp chí"},{"word":"expert","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈɛkspərt/","meaning":"người có kỹ năng trong một lĩnh vực cụ thể; chuyên gia"}],"optionMeanings":["chỉ định","đã chỉ định","thông tin cụ thể","cụ thể là hoàn thành - chi tiết cụ thể (Ns): các chi tiết - cụ thể (Adv): một công cụ có thể *Cấu trúc: - professional (Adj): chuyên nghiệp - tạp chí (N): nhật báo, tạp chí - bài viết (N): bài báo, đồ dùng dịch: Geology Monthlylà một tạp chí chuyênngành với các bài báo được viết DÀNH RIÊNG cho các chuyên gia trong lĩnh vực."]},{"questionNum":"110","question":"------- the year-end sale at Arthur''s Camping Supplies, all winter items are discounted by 25 percent.","bilingual":"-------năm - kết thúc đợt giảm giá tại Đồ dùng cắm trại của Arthur, tất cả các mặt hàng mùa đông đều được giảm giá 25%.","options":["During","Although","As long as","In addition"],"correctIndex":0,"explanation":"Trong câu này chúng ta cần điền một giới từ chỉ thời gian để kết hợp với thời điểm phía sau - During + N: trong suốt… - Although + SV: mặc dù - As long as + SV: chỉ cần, miễn là - In addition, SV: ngoài ra *Cấu trúc: - year - end: cuốinăm - discount (V): giảm giá, (N): tiền bớt, tiền được khấu trừ => discount by: giảm. Dịch: TRONG SUỐT đợt giảm giá cuối năm tại Đồ cắm trại Arthur, tất cả các mặt hàng mùa đôngđều được giảm giá 25%","vocabList":[{"word":"supplies","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/səˈplaɪz/","meaning":"nguồn cung cấp"},{"word":"discount","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈdɪs.kaʊnt/","meaning":"sự giảm giá, chiết khấu; giảm giá, bớt giá"},{"word":"addition","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/əˈdɪʃən/","meaning":"bổ sung; phép toán"},{"word":"percent","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/pərˈsɛnt/","meaning":"một phần trăm"}],"optionMeanings":["Trong thời gian","Mặc dù","Miễn là","Bổ sung"]},{"questionNum":"111","question":"In the ------- future, a hardware store will open o n the corner of Oak Boulevard and Primrose Avenue.","bilingual":"Trong -------trong tương lai, cửa hàng phần cứng sẽ mở ở góc Đại lộ Oak và Đại lộ Primrose.","options":["nears","nearly","nearness","near"],"correctIndex":3,"explanation":"Trong câu này chúng ta cần điền một tính từ bổ nghĩa cho danh từ “future”, tạo thành cụm danh từ - near s (Vs): xích lại gần - nearly (Adv): gần như - nearness (n): trạng tháiở gần - near (Adj): gần *Cấu trúc: - hardware store: cửa hàng kim khí - on the corner of: ở góc - Avenue (N): đại lộ # Venue (N): địa điểm. Dịch: Trong tương lai GẦN, một cửa hàng kim khí sẽ được mởở góc Đại lộ Oak và Đại lộ Primrose","vocabList":[{"word":"future","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/fˈjuʧər/","meaning":"tương lai"},{"word":"corner","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈkɔrnər/","meaning":"giữ ở vịnh; để đạt được lợi thế trên thị trường; ĐẾN"},{"word":"nearly","pos":"Trạng từ (Adverb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈnɪrli/","meaning":"gần như"},{"word":"store","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 4: 400 - 495 đ","ipa":"/stɔr/","meaning":"cửa hàng; nơi bán hàng hóa; cung cấp"}],"optionMeanings":["sắp đến","gần như","sự gần gũi","gần"]},{"questionNum":"112","question":"Mr. Careni requested that -------.-.-from the technical support team come immediately to the Harrisburg office.","bilingual":"","options":["who","someone","which","themselves"],"correctIndex":1,"explanation":"Đáp án đúng là (B) \"someone\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"technical","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ˈtek.nɪ.kəl/","meaning":"có tính kỹ thuật"},{"word":"request","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/rɪˈkwest/","meaning":"yêu cầu"},{"word":"support","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/səˈpɔːrt/","meaning":"trợ giúp"},{"word":"someone","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈsəmˌwən/","meaning":"ai đó"}]},{"questionNum":"113","question":"The time - entry system was ------- ------- unavailable this afternoon, but it is functioning normally now.","bilingual":"thời gian - hệ thống nhập cảnh đã ------- chiều nay không hoạt động được, nhưng hiện tại nó đã hoạt động bình thường.","options":["directly","urgently","precisely","briefly"],"correctIndex":3,"explanation":"Trong câunày chúng ta cần điền một trạng từ để bổ sung nghĩa cho tính từ phía sau. Các đáp án đều là trạng từ nên chúng tacần dựa vào nghĩa để chọn đáp án - directly (Adv): một cách trực tiếp - urgently (Adv): một cách khẩn cấp - precisely (Adv): một cách chính xác - briefly (Adv): một cách ngắn gọn, khônglâu *Cấu trúc: - time -entry system: hệ thống nhập thời gian, chấm công - functioning (N): sự hoạt động, vận hành - normally (Adv): như thường lệ. Dịch: Hệ thống nhập thời gian không khả dụng TRONG MỘT THỜI GIAN NGẮN vào chiều nay nhưng hiện tại nó đang hoạt động bình thường","vocabList":[{"word":"functioning","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈfəŋkʃənɪŋ/","meaning":"hoạt động"},{"word":"directly","pos":"Trạng từ (Adverb)","level":"Level 2: 200 - 300 đ","ipa":"/dɪˈrɛkli/","meaning":"ngay sau đây; khoảnh khắc đó; càng sớm càng"},{"word":"system","pos":"Danh từ (Noun)","level":"Level 4: 400 - 495 đ","ipa":"/ˈsɪstəm/","meaning":"sự kết hợp của những thứ hoặc bộ phận liên quan tạo thành một"}],"optionMeanings":["trực tiếp","khẩn cấp","một cách chính xác","ngắn gọn"]},{"questionNum":"114","question":"The upcoming career fair ------- *- -by more than 100 employers and job-recruiting agencies.","bilingual":"Hội chợ việc làm sắp tới -------hơn 100 nhà tuyển dụng và việc làm - các cơ quan tuyển dụng.","options":["attend","were attended","was attending","will be attended"],"correctIndex":3,"explanation":"Trong câu này chúng ta cần chọnthì đúng của động từ, dựa vào từ “upcomping” để chọn đáp án - attend (V): tham gia - were attended:dùng trong câu bị động của thì quá khứ - was attending: dùng trong thì quá khứ tiếp (D) will be attendeddiễn - will be attended: dùng trong thì tương laihoàn thành *Cấu trúc: - upcoming (Adj): sắp tới - career fair (N): hội chợ việc làm - job -recruiting: tuyển dụng việc làm","vocabList":[{"word":"attending","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/əˈtɛndɪŋ/","meaning":"tham dự"},{"word":"upcoming","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ˈʌpˌkʌm.ɪŋ/","meaning":"sắp xảy ra"},{"word":"employer","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ɪmˈplɔɪ.ɚ/","meaning":"người làm chủ, người sử dụng lao động"},{"word":"recruit","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ri''kru:t/","meaning":"tuyển, chiêu mộ (lính mới); tìm thêm"}],"optionMeanings":["tham dự","đã được tham dự","đã tham dự","sẽ được tham dựdiễn - sẽ tham dự: use in thì tương lai hoàn thành *Cấu trúc: - sắp tới (Adj): sắp xếp - hội chợ nghề nghiệp (N): hội chợ việc làm - công việc -Tuyển dụng: tuyển dụng việc làm Dịch: Hội chợ việc làm sắp xếp tới SẼ CÓ THỂ THAM GIA hơn 100 nhà tuyển dụng và các cơ quan tuyển dụng việc làm."]},{"questionNum":"115","question":"------- theater at Landon Cinema is decorated with a different the me.","bilingual":"-------rạp hát tại LandonCinema được trang trí theo chủ đề khác.","options":["Even","Much","Each","All"],"correctIndex":2,"explanation":"Trong câu này chúng ta cần điền một hạn định từ để bổ sung nghĩa cho danh từ đứng sau và dựa vào nghĩa để chọn đáp án đúng - Even (Adj): cùng, ngang bằng; (Adv): ngaycả, lại còn - Much (Adj/Adv): nhiều, lắm - Each (Adj): mỗi; (đại từ bất định): mỗingười, mỗi vật, mỗi cái; each + N - All (Adj): tất cả, (đại từ): tất cả; All + Ns *Cấu trúc: -be decorated with st: đươc trang trí với cáigì - theme (N): đề tài, chủ đề. Dịch: MỖI RẠP CHIẾU PHIM tạiLandonCinema được trang trí theo một chủ đề khácnhau.","vocabList":[{"word":"different","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/ˈdɪfərənt/","meaning":"không giống nhau; bất thường; đặc biệt"},{"word":"decorate","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈdek.ər.eɪt/","meaning":"trang trí, trang hoàng"}],"optionMeanings":["Thậm chí","Nhiều","Mỗi chiếc","Tất cả"]},{"questionNum":"116","question":"Changes to course content have been halted ------- the Salinas Academy transitions to a new online platform.","bilingual":"Các thay đổi đối với nội dung khóa học đã bị tạm dừng -------Học viện Salinas chuyển sang nền tảng trực tuyến mới.","options":["while","though","regarding","whether"],"correctIndex":0,"explanation":"Trong câu này chúng ta cần điền một liên từ đẳng lập, và có 2 liên từ đẳng lập trongđáp án nên cần dựa vào nghĩa để chọn đáp án - while + SV: trong khi - though + SV: mặc dù - regarding + N/ WithRegardto N: về, đốivới … - whether … or…: liên từ phụ thuộc, hoặc Ahoặc B *Cấu trúc: - Changes (N): các thay đổi - halt (N): sự tạm nghỉ, (V): tạm dừng - transition (N): chuyển đổi - platform (N): nền tảng","vocabList":[{"word":"regarding","pos":"Giới từ (Preposition)","level":"Level 1: Dưới 200 đi","ipa":"/ri´ga:diη/","meaning":"về ( ai/cái gì), về việc, đối với (vấn đề...)"},{"word":"platform","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/''plætfɔ:m/","meaning":"nền, bục, bệ"},{"word":"content","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈkɑntɛnt/","meaning":"thỏa mãn; vừa lòng"},{"word":"whether","pos":"Liên từ (Conjunction)","level":"Level 4: 400 - 495 đ","ipa":"/ˈwɛðər/","meaning":"if"}],"optionMeanings":["trong khi","mặc dù vậy","về","liệu"]},{"questionNum":"117","question":"Bricktown Mayor Julian Trent will ------- help plant flowers in Evans Park this weekend.","bilingual":"Thị trưởng Bricktown Julian Trent sẽ -------giúp trồng hoa ở Công viên Evans vào cuối tuần này.","options":["personal","personalize","personally","personality"],"correctIndex":2,"explanation":"Trong câu này chúng ta cần điền một trạng từ để bổ sung nghĩa cho chủ ngữ. - personal (Adj): cá nhân, dành riêng - personalize (V): cá nhân hoá - personally (Adv): đích thân, với tư các cánhân - personality (N): nhân cách, nhân phẩm *Cấu trúc: - mayor (N): thị trưởng - help + sb + to V: giúp ai đó làm gì - help + V: giúp làm gì - help + V_ing: không thể tránh làm gì đó. Dịch: Thị trưởng của Bricktown, Julian Trent, sẽ ĐÍCH THÂN giúp trồng hoaở công viên Evans vào cuối tuần này.","vocabList":[{"word":"personal","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/''pə:snl/","meaning":"cá nhân, tư, riêng"},{"word":"mayor","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/meɪər/","meaning":"quan chức được bầu làm người đứng đầu điều hành của một thị trấn hoặc"},{"word":"plant","pos":"Noun (Danh từ)","level":"A1","ipa":"/plɑːnt/","meaning":"cây cối, thực vật cảnh"},{"word":"help","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/hɛlp/","meaning":"giúp đỡ"}],"optionMeanings":["cá nhân","cá nhân hóa","cá nhân","cá tính"]},{"questionNum":"118","question":"Pleasereplacepages28t035in the employee handbook with the ------- pages.","bilingual":"","options":["careful","updated","consistent","sizable"],"correctIndex":1,"explanation":"Đáp án đúng là (B) \"updated\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"employee","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ɪmˈplɔɪi/","meaning":"công nhân; người làm việc cho một công ty hoặc một"},{"word":"handbook","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈhændˌbʊk/","meaning":"thủ công; hướng dẫn; hướng dẫn; tài liệu chứa"},{"word":"update","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ʌpˈdeɪt/","meaning":"nâng cấp"},{"word":"page","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/peɪʤ/","meaning":"mảnh giấy; tiếp viên; người hầu"}]},{"questionNum":"119","question":"------- we increased our Internet speed, we can download large documents much faster.","bilingual":"-------chúng tôi đã tăng tốc độ Internet, chúng tôi có thể tải xuống các tài liệu lớn nhanh hơn nhiều.","options":["Since","Provided","Yet","Instead"],"correctIndex":0,"explanation":"Trong câu này chúng ta cần điền một liên từ để tạo thành mệnhđề trạng ngữ chỉ thời gian, bổ sung nghĩa cho mệnhđề chính. Dựa vào nghĩa để chọn - Since: Kể từ khi - Provided: với điều kiện là = provided that - Yet: tuy thế, song - Instead: thay vì *Cấu trúc: - increase (v): tăng >< decrease (v): giảm - speed (N): tốc độ. Dịch: KỂ TỪ KHI chúng ta đã tăng tốc độ Internet, chúng ta có thể tải xuống các tài liệu lớn nhanh hơn nhiều.","vocabList":[{"word":"increase","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ɪnˈkriːs/","meaning":"sự tăng lên; tăng thêm"},{"word":"internet","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈɪntərˌnɛt/","meaning":"Internet"},{"word":"download","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/ˈdaʊn.loʊd/","meaning":"tải xuống"},{"word":"document","pos":"Noun (Danh từ)","level":"B1","ipa":"/ˈdɒk.jə.mənt/","meaning":"tài liệu, văn kiện"}],"optionMeanings":["Vì","Được cung cấp","Tuy nhiên","Thay vào đó"]},{"questionNum":"120","question":"The lead graphic artist decides which photographs submitted by freelancers - ------- ------- to the creative director.","bilingual":"Nghệ sĩ đồ họa chính quyết định những bức ảnh nào được gửi bởi các dịch giả tự do - ------ gửi giám đốc sáng tạo.","options":["are sending","sender","should be sent","send"],"correctIndex":2,"explanation":"Trong câu này chúng ta cần điền động từ và chọn đáp án dựa vào việc dịch nghĩa câu - are sending: đang gửi, dùng cho câu HTTD, dạng chủ động - sender (N): người gửi - should be sent: nên được gửi, dùng chocâu bị động - send (V): gửi *Cấu trúc: - submit (V): đệ trình, nộp - freelancer (N): người làm việc tự do - creative director (N): giám đốc sáng tạo","vocabList":[{"word":"photographs","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈfoʊtəˌgræfs/","meaning":"Ảnh"},{"word":"director","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/daɪˈrek.tɚ/","meaning":"/dɪˈrek.tɚ/"},{"word":"decide","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˌdɪˈsaɪd/","meaning":"lựa chọn; để chọn từ một số tùy chọn; để kết luận;"},{"word":"lead","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/lɛd/","meaning":"tiến hành; hướng dẫn; chỉ đạo; ảnh hưởng"}],"optionMeanings":["đang gửi","người gửi","nên được gửi","gửi"]},{"questionNum":"121","question":"------- you visit the Star Hotel, thecheerful staff makes you feel welcome.","bilingual":"-------bạn ghé thăm StarHotel, đội ngũ nhân viên vui vẻ khiến bạn cảm thấy được chào đón.","options":["Whenever","Whichever","Nevertheless","Altogether"],"correctIndex":0,"explanation":"Trong câu này chúng ta cần điền liên từ chỉ thời gian để tạo nên 1 mệnhđề trạng ngữ chỉ thời gian, bổ sung nghĩa cho mệnhđề chính. Dựa vào nghĩa để chọn đáp án - Whenever: bất cứ khi nào - Whichever: bất cứ cái nào - Nevertheless: tuy nhiên = however - Altogether: cùng nhau *Cấu trúc: - cheerful (Adj): vui vẻ, nồng nhiệt - make + Sb + V: khiến ai đó làm gì. Dịch: BẤT CỨ KHI NÀO bạn ghé thăm Star Hotel, đội ngũ nhân viên thân thiện sẽ khiến bạn cảm thấy được chào đón.","vocabList":[{"word":"whichever","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/wɪˈʧɛvər/","meaning":"tùy theo điều kiện nào"},{"word":"whenever","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/wɛˈnɛvər/","meaning":"bất cứ khi nào"},{"word":"welcome","pos":"Danh từ (Noun)","level":"Level 3: 300 - 400 đ","ipa":"/ˈwɛlkəm/","meaning":"chào mừng"},{"word":"visit","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 4: 400 - 495 đ","ipa":"/ˈvɪzɪt/","meaning":"tạm trú ở đâu đó; ví dụ về việc dành thời gian"}],"optionMeanings":["Bất cứ khi nào","Dù thế nào","Tuy nhiên","Tổng cộng"]},{"questionNum":"122","question":"Ms. Matlou considered a legal career before ------- deciding t o go to business","bilingual":"","options":["strictly","politely","ultimately","slightly"],"correctIndex":2,"explanation":"Đáp án đúng là (C) \"ultimately\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"considered","pos":"Động từ (Verb)","level":"Level 3: 300 - 400 đ","ipa":"/kənˈsɪdərd/","meaning":"được cân nhắc"},{"word":"business","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈbɪznɪs/","meaning":"công ty; doanh nghiệp; buôn bán; thương mại; vấn đề"},{"word":"career","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/kəˈrɪr/","meaning":"sự nghiệp"},{"word":"legal","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˈligəl/","meaning":"của hoặc liên quan đến pháp luật; pháp luật cho phép"}]},{"questionNum":"123","question":"Patrons of the festival enjoying picnic lunches on the concert hall’s lawn is a ------- dating back almost a century.","bilingual":"Những khách hàng quen của lễ hội đang thưởng thức bữa trưa dã ngoại trên bãi cỏ của phòng hòa nhạc là một ------có niên đại gần một thế kỷ.","options":["traditional","tradition","traditionalist","traditions"],"correctIndex":1,"explanation":"Trong câu này chúng ta cần điền một danh từ vì phía trước có hạn định từ “a” và phía sau là động từ. Có 2 danh từ nên dựa vào nghĩa để chọn đáp án - traditional (Adj): mang tính truyền thống - tradition (N): truyền thống - traditionalist (N): người theo chủ nghĩa truyền thống - traditions (Ns): các truyền thống *Cấu trúc: - Patron (N): người bảo trợ - concert hall (N): phòng hoà nhạc - law n (N): bãi cỏ -date (N): ngày, sự hẹn hò (V): bắt đầu, kể từ. Dịch: Những người bảo trợ của lễ hội thưởng thức những bữa trưa dã ngoại trên bãi cỏ của phòng hoà nhạc là một TRUYỀN THỐNG bắt đầu cáchđây gần một thế kỷ.","vocabList":[{"word":"century","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈsɛnʧəri/","meaning":"thời gian một trăm năm"},{"word":"almost","pos":"Trạng từ (Adverb)","level":"Level 3: 300 - 400 đ","ipa":"/ˈɔlˌmoʊst/","meaning":"Gần như"},{"word":"lawn","pos":"Noun (Danh từ)","level":"B1","ipa":"/lɔːn/","meaning":"bãi cỏ"},{"word":"back","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/bæk/","meaning":"một phần của ghế; phần sau của cơ thể con người"}],"optionMeanings":["truyền thống","truyền thống","người theo chủ nghĩa truyền thống","truyền thống"]},{"questionNum":"124","question":"Many people ------- their online shopping carts when they discover what the shipping charge will be.","bilingual":"Nhiều người ------giỏ hàng điện tử của họ khi họ phát hiện ra phí vận chuyển sẽ là bao nhiêu.","options":["eject","abandon","resign","discourage"],"correctIndex":1,"explanation":"Trong câu này chúng ta cần dựa vào nghĩa để chọn đáp án đúng - eject (V): loại ra, phụt ra - abandon (V): từ bỏ - resign (V): từ chức - discourage (V): làm nản lòng *Cấu trúc: - shopping cart (N): giỏ hàng - discover (V): phát hiện, khám phá - shipping charge (N): phí vận chuyển. Dịch: Nhiều người TỪ BỎ các giỏ hàng trực tuyến của họ khi họ phát hiện ra phí vận chuyển sẽ là bao nhiêu.","vocabList":[{"word":"shipping","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 2: 200 - 300 đ","ipa":"/ˈʃɪp.ɪŋ/","meaning":"đang chuyển hàng"},{"word":"charge","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/tʃɑːrdʒ/","meaning":"chi phí, tiền công; tính giá, đòi trả"},{"word":"resign","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/rɪˈzaɪn/","meaning":"bỏ việc, từ chức"},{"word":"cart","pos":"Noun (Danh từ)","level":"B1","ipa":"/kɑːt/","meaning":"xe đẩy hàng"}],"optionMeanings":["đẩy ra","từ bỏ","từ chức","không khuyến khích"]},{"questionNum":"125","question":"The state''s tourism Website provides information on many of the area''s popular -------.","bilingual":"","options":["situations","appeals","demands","attractions"],"correctIndex":3,"explanation":"Đáp án đúng là (D) \"attractions\" phù hợp với cấu trúc ngữ pháp và ngữ cảnh của câu.","vocabList":[{"word":"information","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˌɪn.fɚˈmeɪ.ʃən/","meaning":"thông tin"},{"word":"situation","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˌsɪtʃ.uˈeɪ.ʃən/","meaning":"tình hình"},{"word":"tourism","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈtʊr.ɪ.zəm/","meaning":"du lịch"},{"word":"website","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/ˈweb.saɪt/","meaning":"trang web"}]},{"questionNum":"126","question":"------- interested in learning more about Shana Fabian''s sculptures should attend her talk at Deana Gallery on May 2.","bilingual":"------quan tâm đến việc tìm hiểu thêm về các tác phẩm điêu khắc của Shana Fabian nên tham dự buổi nói chuyện của cô tại Phòng trưng bày Deana vào ngày 2 tháng 5.","options":["Enough","Whoever","Each other","Those"],"correctIndex":3,"explanation":"Trong câu này chúng ta cần điền một đại từ để làm chủ ngữ trong câu và dựa vào nghĩa để chọn. Whoever + SV hoặc Whoever + VThoseở đây dùng trong câu rút gọn mệnhđề: those who are interested in … => those interested in… - Enough (Adj/Adv): đủ, khá - Whoever (đại từ): bất kỳ ai - Each other (đại từ): lẫn nhau - Thos e (đại từ): những ai *Cấu trúc: - be interested in: thích thú điều gì - sculpture (N): tác phẩm nghệ thuật - talk (N): cuộc trò chuyện. Dịch: NHỮNG AI muốn tìm hiểu thêm về các tác phẩm điêu khắc của Shana Fabian nên tham dự buổi trò chuyện của cô tại Phòng trưng bày Deana vào ngày 2 tháng 5.","vocabList":[{"word":"interest","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 3: 300 - 400 đ","ipa":"/ˈɪntəˌrɛst/","meaning":"bận tâm; ngoại tình; tỷ lệ phần trăm trên một khoản vay được trả"},{"word":"gallery","pos":"Noun (Danh từ)","level":"B1","ipa":"/ˈɡæləri/","meaning":"phòng triển lãm"},{"word":"whoever","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/huˈɛvər/","meaning":"Ai"},{"word":"attend","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/əˈtend/","meaning":"tham dự"}],"optionMeanings":["Đủ rồi","Ai","Nhau","Những cái đó"]},{"questionNum":"127","question":"The merger between the Oznaze and Tellurisq companies was- ------- settled following months of tough negotiations.","bilingual":"Việc sáp nhập giữa các công ty Oznaze và Tellurisq là ------đã được giải quyết sau nhiều tháng đàm phán khó khăn.","options":["exactly","instantly","finally","easily"],"correctIndex":2,"explanation":"Trong câu này chúng ta cần dựa vào ng hĩa để chọn đáp án đúng - exactly (Adv): chính xác - instantly (Adv): ngay lập tức - finally (Adv): cuối cùng - easily (Adv): dễ dàng *Cấu trúc: - merger (N): sáp nhập - settle (V): giải quyết - tough (Adj): khó khăn - negotiation (N): cuộc đàm phán. Dịch: Việc sáp nhập giữa các công ty Oznaze và Tellurisq CUỐI CÙNG đã được giải quyết sau nhiều thángđàm phán khó khăn.","vocabList":[{"word":"exactly","pos":"Trạng từ (Adverb)","level":"Level 3: 300 - 400 đ","ipa":"/ɪgˈzæktli/","meaning":"chính xác"}],"optionMeanings":["chính xác","ngay lập tức","cuối cùng","dễ dàng"]},{"questionNum":"128","question":"Auto parts are shipped ------- two to three days unless the customer requests expedited delivery.","bilingual":"Phụ tùng ô tô được vận chuyển ------ hai đến ba ngày trừ khi khách hàng yêu cầu giao hàng nhanh.","options":["within","here","afterward","perhaps"],"correctIndex":0,"explanation":"Trong câu này chúng ta cần dựa vào nghĩa để chọn đáp án đúng - within: trong vòng - here: ở đây - afterward: sau đó - perhaps: có lẽ *Cấu trúc: - Auto parts: phụ tùngô tô - expedited delivery: giao hàng hoả tốc","vocabList":[{"word":"customer","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/ˈkʌs.tə.mɚ/","meaning":"khách hàng"},{"word":"delivery","pos":"Danh từ (Noun)","level":"Level 1: Dưới 200 đi","ipa":"/dɪˈlɪv.ɚ.i/","meaning":"sự phân phát, giao hàng"},{"word":"request","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/rɪˈkwest/","meaning":"yêu cầu"},{"word":"unless","pos":"Liên từ (Conjunction)","level":"Level 4: 400 - 495 đ","ipa":"/ənˈlɛs/","meaning":"không phải trước đó; loại trừ; cấm; ngoại trừ; ngoài ra"}],"optionMeanings":["trong vòng","tại đây","sau đó (D ) có lẽ Giải thích thích: Trong câu này chúng ta cần dựa vào nghĩa để chọn đáp án đúng - bên trong: trong vòng - ở đây: ở đây - sau đó: sau đó - có lẽ: có lẽ *Cấu trúc: - Phụ tùng ô tô: phụ tùng ô tô - giao hàng nhanh: giao hàng bạch tốc dịch: Phụ tùng ô tô được vận chuyển TRỌNG VÒNG hai ngày đến ba ngày trừ khi khách hàng yêu cầu giao hàng nhanh.","đột ngột"]},{"questionNum":"129","question":"The interior designer selected some very ------- colors for the lobby walls.","bilingual":"Nhà thiết kế nội thất đã lựa chọn một số rất ------màu sắc cho các bức tường tiền sảnh.","options":["massive","intense","direct","sudden"],"correctIndex":1,"explanation":"Trong câu này chúng ta cần dựa vào nghĩa để chọn đáp án đúng - massive (Adj): to lớn, ồạt - intense (Adj): có cườngđộ mạnh - direct (Adj): thẳng, ngay lập tức, trực tiếp - sudden (Adj): đột ngột *Cấu trúc: - direct (V): chỉ dẫn - interior (Adj): nội, bên trong, (N): phần trong, nộivụ","vocabList":[{"word":"interior","pos":"Tính từ (Adjective)","level":"Level 3: 300 - 400 đ","ipa":"/ˌɪnˈtɪriər/","meaning":"bên trong một tòa nhà; phần nội địa của một quốc gia"},{"word":"selected","pos":"Động từ (Verb)","level":"Level 2: 200 - 300 đ","ipa":"/səˈlɛktɪd/","meaning":"đã chọn"},{"word":"direct","pos":"Tính từ (Adjective)","level":"Level 2: 200 - 300 đ","ipa":"/dɪˈrɛkt/","meaning":"thẳng; thẳng thắn; thông thoáng"},{"word":"lobby","pos":"Danh từ / Động từ (Noun / Verb)","level":"Level 1: Dưới 200 đi","ipa":"/lɒb.i/","meaning":"hành lang"}],"optionMeanings":["đồ sộ","mãnh liệt","trực tiếp","đột ngột"]},{"questionNum":"130","question":"Experts recommend that the cooling system be checked by a service technician at regular -------.","bilingual":"Các chuyên gia khuyên rằng hệ thống làm mát nên được kiểm tra định kỳ bởi kỹ thuật viên dịch vụ ------.","options":["expanses","intervals","classifications","detachments"],"correctIndex":1,"explanation":"Trong câu này chúng ta cần dựa vào nghĩa để chọn đáp án đúng - expanses (Ns): dải, dải rộngđất, sự pháttriển - intervals (Ns): khoảng cách, quãng - classifications (Ns): sự phân loại - detachments (Ns): sự tách rời *Cấu trúc: - cooling system: hệthống làm lạnh - service technician: kỹ thuật viên dịch vụ - regular (Adj): đều đều","vocabList":[{"word":"technician","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/tekˈnɪʃ.ən/","meaning":"kỹ thuật viên"},{"word":"recommend","pos":"Động từ (Verb)","level":"Level 1: Dưới 200 đi","ipa":"/rekə''mend/","meaning":"giới thiệu, tiến cử (người, vật...)"},{"word":"service","pos":"Danh từ (Noun)","level":"Level 2: 200 - 300 đ","ipa":"/''sə:vis/","meaning":"sự phục vụ, sự hầu hạ"},{"word":"regular","pos":"Tính từ (Adjective)","level":"Level 1: Dưới 200 đi","ipa":"/ˈreɡ.jə.lɚ/","meaning":"đều đặn, thường xuyên"}],"optionMeanings":["sự mở rộng","các khoảng thời gian","phân loại","biệt đội"]}]'::jsonb,
